import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const assetsDir = path.join(root, "dist", "assets");
const permissionsPath = path.join(
  root,
  "src-tauri",
  "permissions",
  "autogenerated",
  "commands",
  "mobile-commands.toml"
);
const setupPagePath = path.join(root, "src", "pages", "SetupPage.tsx");
const forbiddenFilePatterns = [
  /SecureWebSocket/i,
  /WebSocketBackendTransport/i,
  /PasswordInputModal/i,
  /ReconnectingOverlay/i,
  /libsodium/i,
];
const forbiddenContent = [
  "new WebSocket(",
  "baseBackendAddr",
  "baseBackendPort",
  "baasAutoPassword",
  "updater://backend-ready",
  "/ws/control",
  "/auth/remember",
  "Password proof",
  "Control connection",
  "ControlConnection",
  "rememberControlSession",
  "PasswordInputModal",
  "crypto_secretstream",
];
const forbiddenSetupContent = [
  "updater://backend-ready",
  "baseBackendAddr",
  "baseBackendPort",
  "baasAutoPassword",
  "submitPassword(",
  "updater_reset_backend_auth_and_restart",
];
const requiredIpcCommands = [
  "backend_ipc_start",
  "backend_ipc_close",
  "backend_ipc_open_channel",
  "backend_ipc_close_channel",
  "backend_ipc_send_json",
  "backend_ipc_send_bytes",
  "backend_ipc_subscribe",
  "backend_ipc_recv",
  "backend_ipc_benchmark_webview_copy",
  "backend_ipc_webview_benchmark_config",
  "backend_ipc_finish_webview_benchmark",
];

async function walk(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await walk(fullPath)));
    } else if (entry.isFile()) {
      files.push(fullPath);
    }
  }
  return files;
}

const files = await walk(assetsDir);
const badNames = files
  .map((file) => path.relative(root, file))
  .filter((file) => forbiddenFilePatterns.some((pattern) => pattern.test(file)));

if (badNames.length > 0) {
  throw new Error(`Tauri build emitted forbidden WebSocket/auth chunks:\n${badNames.join("\n")}`);
}

const jsFiles = files.filter((file) => file.endsWith(".js"));
const badContent = [];
for (const file of jsFiles) {
  const content = await readFile(file, "utf8");
  for (const needle of forbiddenContent) {
    if (content.includes(needle)) {
      badContent.push(`${path.relative(root, file)} contains ${needle}`);
    }
  }
}

if (badContent.length > 0) {
  throw new Error(`Tauri build contains forbidden WebSocket/auth code:\n${badContent.join("\n")}`);
}

const permissions = await readFile(permissionsPath, "utf8");
const missingCommands = requiredIpcCommands.filter(
  (command) => !permissions.includes(`"${command}"`)
);
if (missingCommands.length > 0) {
  throw new Error(`Tauri permissions do not allow backend IPC commands:\n${missingCommands.join("\n")}`);
}

const setupPage = await readFile(setupPagePath, "utf8");
const badSetupContent = forbiddenSetupContent.filter((needle) => setupPage.includes(needle));
if (badSetupContent.length > 0) {
  throw new Error(
    `Desktop setup page contains forbidden localhost/auth startup code:\n${badSetupContent.join("\n")}`
  );
}
if (!setupPage.includes("launch: false")) {
  throw new Error("Desktop setup page must run updater workflow with launch: false");
}
if (!setupPage.includes("startAuthFlow()")) {
  throw new Error("Desktop setup page must initialize the shared-memory backend through BackendStore");
}

console.log("tauri transport build check passed");
